window.REPORT_PRELOAD_CACHE["ED.html"] = {"version":"1d38b2d5b3252bd2b7f40164673a33e4f03ecbb70bb150fd05b4751803cc45f5","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>爱迪生联合电气 Consolidated Edison (NYSE: ED) 深度研究报告：纽约公用事业百年堡垒、AI算力用电激增与防御性股息红利复利引擎</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#060E1A',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n edblue: {\n 300: '#7DD3FC',\n 400: '#38BDF8',\n 500: '#0284C7',\n 600: '#026E9D',\n 700: '#034E70',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n teal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n /* 自定义滚动条与机构研报细节排版 */\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n /* 打印友好优化 */\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n /* 卡片悬浮微光与上移过渡 */\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n /* 侧边导航激活态：电力电网蓝渐变标识 */\n .nav-link.active {\n background: linear-gradient(90deg, rgba(2, 132, 199, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #38BDF8;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-edblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-edblue-500 via-teal-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-edblue-400 to-edblue-600 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n ED\n </div>\n <div>\n <div class=\"text-[11px] text-edblue-400 font-semibold tracking-wider uppercase\">NYSE: ED · Utility Dividend Aristocrat</div>\n <div class=\"text-sm font-bold leading-tight\">爱迪生联合电气 深度研报</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">ED 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与 Q3 财报拆解</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 纽约电网垄断与 AI 算力用电增量</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 美国标杆公用事业横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与股息复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与宏观利率风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球公用事业与红利资产研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-edblue-400 via-edblue-500 to-edblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-edblue-500/25\">\n ED\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-edblue-400 bg-edblue-500/15 px-2 py-0.5 rounded\">NYSE: ED</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">爱迪生联合电气研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 纽约市与威彻斯特百年电力天然气垄断巨头 · 连续 51+ 年提息股息伯爵\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$106.50 <span class=\"text-slate-400 text-[10px]\">($89.2-$109.8)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">2026E 调整后 EPS 指引</span>\n <span class=\"font-mono font-bold text-emerald-400\">$6.05–$6.15 <span class=\"text-slate-400\">(上调)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值与股息率</span>\n <span class=\"font-mono font-bold text-edblue-300\">~17.5x P/E · 股息率 ~3.33%</span>\n </div>\n </div>\n\n <!-- 七大核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-edblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与 Q3 财报拆解</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>纽约电网垄断与 AI 算力用电增量</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>美国标杆公用事业横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与股息复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与宏观利率风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-edblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-edblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-edblue-500 to-edblue-600 hover:from-edblue-600 hover:to-edblue-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <!-- 顶部研报元数据标签栏 -->\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-edblue-500/15 text-edblue-700 dark:text-edblue-400 font-bold border border-edblue-500/30\">评级：审慎增持 / 核心防御避险底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 业绩超预期上调指引与 NYC 电网资本开支周期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: ED</span>\n </div>\n </div>\n\n <!-- Hero 标题卡片 -->\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <!-- 背景蓝色点阵纹理 -->\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#38BDF8 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-edblue-500/20 border border-edblue-400/40 text-edblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-edblue-400 animate-pulse\"></span>\n <span>CORE THESIS · 纽约市垄断电网与天然气特许经营权 × Q3净利$766M超预期 × 连续51年提息股息伯爵</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 爱迪生联合电气 Consolidated Edison (NYSE: ED) 深度研究报告：纽约公用事业百年堡垒、AI算力用电需求飙升与防御性股息红利复利引擎\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 作为美国历史最悠久、最具防御韧性的公用事业巨头之一，爱迪生联合电气（Con Edison）交出亮眼的 <strong class=\"text-white\">2026Q3 财报</strong>：单季实现净利润 <strong class=\"text-edblue-300\">$7.66亿美元</strong>，摊薄 EPS 达 <strong class=\"text-emerald-400\">$2.07</strong>。得益于纽约州公共服务委员会（NYPSC）稳定的监管收益率回报框架及大纽约地区数据中心与电气化用电需求的持续超预期，管理层顺势将 <strong class=\"text-white\">2026 全年调整后 EPS 指引上调至 $6.05–$6.15</strong>。\n 公司维持季度派息 <strong class=\"text-edblue-300\">$0.8875/股</strong>（年化 <strong class=\"text-white\">$3.55</strong>，股息率约 <strong class=\"text-emerald-400\">3.2%</strong>），已连续 51 年以上稳健上调股息，是应对宏观降息周期与市场波动不可或缺的顶级基石资产。\n </p>\n\n <!-- 核心投资结论高亮条 -->\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">监管资产基础 (Rate Base) 护城河</div>\n <div class=\"text-white font-semibold\">深耕纽约市与威彻斯特区，近乎 100% 垄断特许配送权，年均监管资产基数稳健复合增长 6%–8%</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 盈利超预期与指引上调</div>\n <div class=\"text-edblue-300 font-semibold\">Q3 净利润 $766M / EPS $2.07，全年调整后 EPS 上调至 $6.05–$6.15，盈利可见度极高</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">AI 算力与热泵电气化双重催化</div>\n <div class=\"text-emerald-400 font-semibold\">大纽约地区金融科技与 AI 算力中心用电需求飙升，叠加建筑脱碳热泵改造带来长线成长动力</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <!-- KPI 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与参考股价</span>\n <span class=\"p-1.5 rounded-lg bg-edblue-500/15 text-edblue-600 dark:text-edblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$37.1B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$106.50</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 估值稳健修复，在宏观降息及避险资金抱团优质公用事业背景下稳居历史高位区间。\n </p>\n </div>\n\n <!-- KPI 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>2026Q3 净利润与摊薄 EPS</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$766M</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">EPS $2.07</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n Q3 旺季用电需求稳固，叠加输配电费率机制顺利兑现，单季盈利超越华尔街一致预期。\n </p>\n </div>\n\n <!-- KPI 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>全年调整后 EPS 指引</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$6.05–$6.15</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">指引上调</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着前三季度业绩落地，管理层上调全年 EPS 区间，展现出极强的公用事业盈利成长兑现度。\n </p>\n </div>\n\n <!-- KPI 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>季度股息与远期股息率</span>\n <span class=\"p-1.5 rounded-lg bg-edblue-500/15 text-edblue-600 dark:text-edblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$0.8875</span>\n <span class=\"text-xs font-bold text-edblue-600 dark:text-edblue-400 bg-edblue-500/15 px-2 py-0.5 rounded\">股息率 ~3.33%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 连续 51+ 年无间断上调股息，构筑起美股标普 500 顶级红利贵族的高确定性防线。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务架构与 Q3 财报拆解 (Business & Q3 Financial Breakdown)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-edblue-600 dark:text-edblue-400\">Section 01 · Business Architecture & Q3 Earnings</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与 2026Q3 财报深度拆解：两大核心公用事业板块与盈利超预期驱动</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 营业收入 ~$41.2B · 净利润 $766M (EPS $2.07)</span>\n </div>\n\n <!-- 交互式 Chart.js 双视图切换面板 -->\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <!-- 左侧：双视图图表 -->\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 营业收入与净利润演进路径</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">得益于纽约电网费率重组与资本开支投放，净利润稳步上升至 ~$19.5亿 平台</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_profit')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-edblue-600 dark:text-edblue-400 shadow-sm transition cursor-pointer\">视图A：营收与净利润演进</button>\n <button onclick=\"switchBizChart('segments')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：核心业务分部贡献拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <!-- 右侧：结构性拆解核心洞察 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">2026Q3 财报核心亮点与盈利驱动</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-edblue-500/15 text-edblue-600 dark:text-edblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Q3 净利润达 $7.66 亿（EPS $2.07），强势超越共识</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核心子公司 CECONY（纽约爱迪生电力公司）在夏季高温用电高峰中实现电量与输配费率双升，叠加严控运营成本，单季净利润表现显著优于季节性历史均值。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">全年调整后 EPS 指引上调至 $6.05–$6.15</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 鉴于前九个月各监管业务执行顺利及输配电资产基数稳健扩张，管理层顺势将全年盈利区间上限与下限同步上调，兑现公用事业稀缺的高成长兑现度。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">清晰的监管费率协议与资本回报框架</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 纽约州公共服务委员会（NYPSC）多 年期电价与天然气配送费率协议（Rate Plans）确保了资本开支享有法定的公平回报率（Allowed ROE），消除了绝大部分商业运营不确定性。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">信用评级保障</span>\n <span class=\"font-bold text-edblue-600 dark:text-edblue-400\">S&P A- / Moody's A2 投资级标杆</span>\n </div>\n </div>\n </div>\n\n <!-- 四大业务与战略资产分部详细卡片矩阵 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <!-- 分部 1：CECONY 电力业务 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-edblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-edblue-500/15 text-edblue-700 dark:text-edblue-400 text-xs font-bold\">核心现金牛支柱 · 占总收益 ~75%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">纽约电力垄断配送</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 纽约爱迪生电力公司 (CECONY - Electric)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 服务整个纽约市（曼哈顿、布鲁克林、皇后区、布朗克斯、斯塔滕岛）及威彻斯特郡的逾 350 万电力客户。拥有全球闻名的高可靠性地下输配电电网网架，是支撑曼哈顿金融中枢与庞大商业写字楼群运转不可或缺的生命线。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>服务人口 1000万+ 核心高密度区</span>\n <span class=\"text-edblue-600 dark:text-edblue-400 font-semibold\">法定特许经营无竞争威胁</span>\n </div>\n </div>\n\n <!-- 分部 2：CECONY 气体与蒸汽业务 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/15 text-teal-700 dark:text-teal-400 text-xs font-bold\">公用事业协同 · 燃气与全球最大蒸汽网</span>\n <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">蒸汽系统独家垄断</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 气体与全美最大商业蒸汽系统 (Gas & Steam)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 为曼哈顿及周边逾 110 万天然气客户提供安全可靠的供气服务；同时运营着全球规模最大、历史悠久的<strong>曼哈顿商业区域蒸汽供热系统</strong>，为成百上千栋摩天大楼及医院提供高效集中供暖与制冷，构筑起极高的行业进入壁垒。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>曼哈顿地标建筑核心供暖支撑</span>\n <span class=\"text-teal-600 dark:text-teal-400 font-semibold\">稳定现金流基本盘</span>\n </div>\n </div>\n\n <!-- 分部 3：O&R 区域电力与天然气 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">卫星郊区网络 · 稳健区域增长</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Orange and Rockland</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">3. Orange and Rockland Utilities (O&R)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 子公司 O&R 服务于纽约州东南部以及新泽西州北部、宾夕法尼亚州东北部的部分地区，为约 30 万电力客户和 14 万天然气客户提供优质服务，受益于纽约通勤圈郊区人口与住宅扩张带来的持续资本开支投入。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>跨州卫星郊区服务网络</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">稳健的区域费率回报增量</span>\n </div>\n </div>\n\n <!-- 分部 4：Clean Energy Transmission 输电创新 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/15 text-indigo-700 dark:text-indigo-400 text-xs font-bold\">新能源输配转型 · 绿色转型投资</span>\n <span class=\"font-mono text-xs font-bold text-indigo-600 dark:text-indigo-400\">Clean Energy Ventures</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">4. 清洁能源传输与战略合资项目 (CETV)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 顺应纽约州《气候领导与社区保护法案》（CLCPA）要求，公司积极推进大型输电项目（如输送州北部可再生清洁能源至纽约市的高压输电线路），在确保电网安全与低碳转型中持续扩张受监管资产基数（Rate Base）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>紧跟 NY 绿色零碳政策红利</span>\n <span class=\"text-indigo-600 dark:text-indigo-400 font-semibold\">资产基数年均扩容 6%-8%</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 纽约电网垄断与 AI 算力用电增量 (NYC Grid Monopoly & AI Surge)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · NYC Grid Monopoly & AI Power Demand</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 纽约电网自然垄断与 AI 算力、热泵电气化用电需求飙升</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 纽约绝无仅有的百年输配电特许权)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧：四重护城河深度解析 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <!-- 护城河 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-edblue-500/15 text-edblue-600 dark:text-edblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">纽约市与威彻斯特绝对特许配送垄断</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 曼哈顿及整个纽约市密集的地下电网由 Con Edison 独家铺设和运营。物理空间的极端拥挤与巨额前期沉没资本令任何潜在竞争对手绝无可能复制第二套输配电网络，构成绝对的自然垄断壁垒。\n </p>\n </div>\n\n <!-- 护城河 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">NYPSC 监管资产基础（Rate Base）回报保障</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 公司所有资本开支均可纳入监管资产基数，并通过与纽约州公共服务委员会（NYPSC）达成的多 年期费率协议锁定合法的允许回报率（Allowed ROE），确保每投入一美元电网升级都能转化为稳定的盈利。\n </p>\n </div>\n\n <!-- 护城河 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI 算力中心与华尔街金融高密度用电增量</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 随着大纽约地区金融机构全面拥抱人工智能、高频量化交易中心及本地云计算数据中心密集落地，大都市核心区对超高可靠性、不间断大功率电力的需求呈爆发式增长，直接推高电网负荷基数。\n </p>\n </div>\n\n <!-- 护城河 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">建筑电气化脱碳与热泵改造浪潮</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 纽约市严格的碳排放法规（如 Local Law 97）迫使成千上万栋商业和住宅建筑放弃化石燃料供暖，大规模转向高效电动热泵系统，为电网输配电量创造了数十年长青的结构性增长点。\n </p>\n </div>\n </div>\n\n <!-- 右侧：五维护城河雷达图 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">美国核心公用事业巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Con Edison (ED) vs NextEra (NEE) vs Duke Energy (DUK)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 美国标杆公用事业横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-edblue-600 dark:text-edblue-400\">Section 03 · US Regulated Utilities Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 美国标杆公用事业横向对比：百年股息贵族、估值与区域监管优势</h2>\n </div>\n <!-- 交互式筛选按钮 -->\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-edblue-500 text-white shadow-sm transition cursor-pointer\">全部标杆</button>\n <button onclick=\"filterCompetitors('regulated')\" data-filter=\"regulated\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">纯受监管公用事业</button>\n <button onclick=\"filterCompetitors('hybrid')\" data-filter=\"hybrid\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">新能源与综合巨头</button>\n </div>\n </div>\n\n <!-- 横向对比矩阵表格 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心服务区域</th>\n <th class=\"py-4 px-4 min-w-[140px]\">业务模式特征</th>\n <th class=\"py-4 px-4 min-w-[100px]\">远期 P/E</th>\n <th class=\"py-4 px-4 min-w-[115px]\">远期股息率</th>\n <th class=\"py-4 px-4 min-w-[115px]\">连涨股息年数</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优势与投资定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <!-- 行 1：爱迪生联合电气 ED 基准 -->\n <tr data-category=\"regulated\" class=\"bg-edblue-500/5 dark:bg-edblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-edblue-500 text-white text-[10px] font-extrabold\">核心研报标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">爱迪生联合电 (ED)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">NYC & Westchester</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">纽约市与威彻斯特郡(特许垄断)</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-edblue-500/15 text-edblue-700 dark:text-edblue-400\">100% 受监管输配电与气</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~17.5x</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~3.33%</td>\n <td class=\"py-4 px-4 font-mono font-bold text-edblue-600 dark:text-edblue-400\">51 年+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>顶级防御性避险资产：</strong>纯受监管公用事业，无非监管发电资产敞口，现金流极其透明稳健，是应对市场动荡的天然避风港。\n </td>\n </tr>\n\n <!-- 行 2：NextEra Energy NEE -->\n <tr data-category=\"hybrid\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">NextEra Energy (NEE)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">佛罗里达州 + 全美清洁能源</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">佛罗里达州(FPL) + 全美风光新能源</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">监管电力 + 全美最大绿能商</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~22.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~2.75%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">29 年+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>新能源成长龙头：</strong>兼具佛罗里达州高速人口流入的监管电网与全美第一的风光新能源开发商双重身份，成长性更强但估值溢价较高。\n </td>\n </tr>\n\n <!-- 行 3：Duke Energy DUK -->\n <tr data-category=\"regulated\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Duke Energy (DUK)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">卡罗来纳州与中西部</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">北卡、南卡、佛州、印第安纳等</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-teal-500/15 text-teal-700 dark:text-teal-400\">大型多州受监管电力与气</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~17.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~3.95%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">26 年+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>高股息率平衡之选：</strong>业务布局美国东南部经济蓬勃发展地区，股息率略高于 ED，监管管辖区多元化但面临多州费率审批的协调成本。\n </td>\n </tr>\n\n <!-- 行 4：Southern Company SO -->\n <tr data-category=\"regulated\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Southern Company (SO)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">佐治亚州、阿拉巴马州</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">美国东南部大本营</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">受监管电力 + 核电与基建</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~18.5x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~3.40%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">23 年+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>南部工业与 AI 用电强音：</strong>受益于佐治亚州近年来蓬勃发展的制造业回流与大型数据中心集群落地，核电与传统电力供应带来稳定现金流。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <!-- 配套 Chart.js 横向条形图：远期 P/E 与股息率对比 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">美国主要公用事业标杆远期市盈率 (Forward P/E) 与股息率对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Con Edison (ED) 以纯受监管的稳定资产基数和 51 年连续提息纪录，保持极具性价比的估值中枢与股息安全边际</p>\n </div>\n <span class=\"text-xs font-semibold text-edblue-700 dark:text-edblue-400 bg-edblue-500/15 px-2.5 py-1 rounded\">51年连涨股息贵族</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与股息复利推演 (Financial Health & Dividend Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 . Financial Health & Dividend Aristocrat Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：资本开支、资产基数增长与股息复利推演</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">连续 51 年提息 · 投资级资产负债表长线保值</span>\n </div>\n\n <!-- 1. 财务健康度四大硬核指标卡 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-edblue-600 dark:text-edblue-400 uppercase\">Regulated Rate Base Growth</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">6% – 8%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 依托庞大的电网更新与绿色输配电资本开支计划，受监管资产基数每年稳步扩张，为长线盈利增长奠定坚实法律基础。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">2026E Adjusted EPS Guidance</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$6.05–$6.15</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 业绩超预期带动全年指引上调，摊薄 EPS 持续稳健增长，派息率维持在健康合理的 55%–60% 区间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Credit Rating & Debt Profile</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">A- / A2 (Stable)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 标普 A- 与穆迪 A2 投资级评级，长期债务结构搭配合理，在降息周期中融资成本优势逐步显现。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Annual Dividend Yield</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~3.33%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 季度派息 $0.8875（年化 $3.55），连续 51 年无间断提息，是名副其实的公用事业“股息伯爵”。\n </p>\n </div>\n </div>\n\n <!-- 2. 交互式 Chart.js 双轴演进图 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 调整后摊薄 EPS 与每股年化分红增长趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">得益于纽约电网资本开支转化为优质资产基数，EPS 与分红实现同步稳健复合增长</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-edblue-700 dark:text-edblue-400 bg-edblue-500/15 px-2.5 py-1 rounded\">51年连续提息纪录保持者</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 3. 交互式组件：ED“股息伯爵”DRIP 复利与成本股息率（Yield on Cost）动态推演器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-edblue-400 font-bold\">\n <span>DIVIDEND ARISTOCRAT COMPOUNDING ENGINE · 51年提息复利模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">爱迪生联合电气 “股息伯爵” DRIP 复利与成本股息率（Yield on Cost）动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $106.50 | 年化股息 $3.55/股（起始毛股息率 3.33%）| 支持不同地区美股股息预扣税率测算</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-edblue-500/15 border border-edblue-400/30 text-xs font-semibold text-edblue-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#0284C7] cursor-pointer\">\n <span>开启股息自动再投资 (DRIP)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧参数控制区 -->\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <!-- 本金滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投入本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <!-- 年限滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">10 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <!-- 股息与EPS增速滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均股息与 EPS 增长率 (公用事业中高增速)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">5.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"8\" step=\"0.5\" value=\"5.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <!-- 预扣股息税率选择按钮组 -->\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">美股股息预扣税率（Withholding Tax）情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(0)\" data-tax=\"0\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-edblue-400 transition cursor-pointer\">\n 0% 免税账户<br><span class=\"text-[10px] text-slate-400\">IRA/RRSP等</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.10)\" data-tax=\"0.1\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-edblue-500 text-white border border-edblue-400 shadow transition cursor-pointer\">\n 10% 协定税率<br><span class=\"text-[10px] text-slate-200\">中美税收协定</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.30)\" data-tax=\"0.3\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-edblue-400 transition cursor-pointer\">\n 30% 标准预扣<br><span class=\"text-[10px] text-slate-400\">新加坡/香港等</span>\n </button>\n </div>\n </div>\n </div>\n\n <!-- 右侧四大实时测算结果卡片 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产 (含税后分红)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$65,240</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +117.5%</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末年度税后股息现金流</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-edblue-300 mt-1.5\">$2,380</div>\n <div id=\"sim-monthly-div\" class=\"text-xs text-slate-400 mt-1.5\">折合每月被动现金流 ~$198</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末税后成本股息率 (Yield on Cost)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">7.93%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">相对于初始投入本金的每年分红回报</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">持有期累计获配税后股息总额</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$16,450</div>\n <div id=\"sim-shares-end\" class=\"text-xs text-slate-400 mt-1.5\">期末持仓股数：452.1 股 (起始 281.7 股)</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4. 华尔街多空核心分歧对比 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">降息周期红利 + 纽约电网刚需</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>降息周期下无风险利率下行的估值修复：</strong>随着美联储宽松货币政策推进，公用事业作为类固定收益资产，其 ~3.33% 的稳定股息对机构资金极具吸引力。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>AI 数据中心与建筑热泵带来的结构性用电增量：</strong>曼哈顿及周边庞大的商业地产电气化转型与算力升级确保了电网资产基数高速扩张。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>纯受监管业务的零风险敞口：</strong>彻底剥离了以往非监管新能源开发业务的波动干扰，盈利透明度达行业顶级水平。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">长端利率波动 + 资本开支压力</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>美债长端收益率反弹的估值压制：</strong>若美国长期国债收益率再度冲高，公用事业股息率与美债无风险收益率的息差收窄，可能引发短期板块估值回撤。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>庞大资本开支带来的外部融资需求：</strong>为满足电网脱碳升级，ED 每年需要持续开展数十亿美元的资本开支，存在潜在的股权融资或债务再融资成本压力。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>纽约州严格的监管及环保合规约束：</strong>纽约州公共服务委员会（NYPSC）对费率调整审批极为严苛，且碳中和法律对传统燃气业务提出长期替代挑战。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-edblue-600 dark:text-edblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景估值推演与公用事业资产配置纪律</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：高确定性防御避险底仓 · 16.5x–17.5x 逢宏观回调分批布局</span>\n </div>\n\n <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <!-- 牛市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">19.0x–20.5x P/E ($115–$125)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>美联储加速降息推低无风险利率，公用事业板块迎来估值戴维斯双击；AI 算力中心与纽约商业地产热泵改造带动用电需求超预期增长，监管费率协议获批更为优厚。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 含息潜在年化总回报：+14% 至 +18%\n </div>\n </div>\n\n <!-- 基准情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-edblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-edblue-500/15 text-edblue-700 dark:text-edblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-edblue-600 dark:text-edblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">17.0x–18.0x P/E ($103–$110)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026–2028 年间资产基数稳健复合增长 6%–8%，EPS 兑现指引并实现中速增长，股息按惯例逐年温和上调，估值维持在 17x–18x 历史合理中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-edblue-600 dark:text-edblue-400\">\n 含息稳健年化总回报：+8.5% 至 +10.5%（高确定性收息）\n </div>\n </div>\n\n <!-- 熊市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">14.5x–15.5x P/E ($88–$95)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>美国通胀反弹导致长端美债收益率重回高位，对高股息公用事业板块估值形成显著杀估值压制；或纽约监管机构在费率审批中压低允许回报率（ROE）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 含息潜在回撤：-8% 至 -14%（强劲股息率提供坚实底部）\n </div>\n </div>\n </div>\n\n <!-- 2. 四大核心风险矩阵 -->\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 宏观长端利率波动风险</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">美债收益率上升对高股息公用事业估值的压制</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 作为类固定收益资产，当 10 年期美债收益率大幅波动时，公用事业股息率与无风险利率的吸引力对比会直接影响短线股价表现。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 纽约监管环境与费率审批周期</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">NYPSC 费率裁决与允许回报率（Allowed ROE）变动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 公司盈利高度依赖纽约州公用事业监管委员会的费率裁决。若监管机构在后续周期中未能充分考虑通胀及资本成本上升，可能对盈利增长产生约束。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">03 · 大规模资本开支与外部融资压力</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">电网现代化与绿色转型带来的巨额资本开支需求</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 每年数十亿美元的资本开支需要通过债务和股权融资平衡。若资本成本高企，可能在短期内摊薄每股收益增速。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 极端天气事件与电网韧性考验</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">极端气候对城市地下及架空电网的安全运维挑战</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 东北部极端风暴、飓风或极端高温可能导致突发运维成本上升，考验公司电网防灾减灾与保险赔付能力。\n </p>\n </div>\n </div>\n </div>\n\n <!-- 3. 机构级组合配置纪律横幅 -->\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-edblue-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与公用事业避险策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 纯受监管公用事业底仓定位</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 在宏观经济波动或地缘政治不确定性升温时，将 ED 作为投资组合中不可或缺的低贝塔防御锚，提供稳健的现金流收益。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-edblue-300 mb-1\">2. 宏观利率回落期逢低加仓</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 当长端美债收益率上升导致股价回撤至 <strong>$98–$102（股息率回升至 3.5%+）</strong>时，具备极佳的左侧分批逢低加仓性价比。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 账户税务效率与 DRIP 再投资</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 优先置于享受税收优惠或协定税率的账户中，通过长期开启股息自动再投资（DRIP），充分释放 51 年连续提息的复利效应。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-edblue-500/15 text-edblue-700 dark:text-edblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的公用事业核心指标（勾选状态自动本地保存），持续校验爱迪生联合电气的垄断护城河与股息增长安全垫：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <!-- KPI 1 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. CECONY 核心电力与天然气监管资产基数稳健扩容 6%–8%</span>\n <span class=\"text-[11px] font-mono text-edblue-600 dark:text-edblue-400 font-semibold shrink-0\">资产基数核心锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认电网资本开支是否顺利转化为受监管资产基数，保障未来几年内每股收益与股息的自然复合增长。\n </p>\n </div>\n </label>\n\n <!-- KPI 2 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 全年调整后 EPS 是否顺利达标或超越 $6.05–$6.15 指引区间</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利兑现晴雨表</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 净利润达 $7.66亿（EPS $2.07），需持续跟踪第四季度取暖季用电与天然气需求是否支撑全年指引顺利兑现。\n </p>\n </div>\n </label>\n\n <!-- KPI 3 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. NYPSC 纽约州监管费率协议（Rate Plans）审批进展与允许 ROE</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">政策法规护城河</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪各主要子公司与州监管委员会的费率重组谈判结果，确保法定允许回报率（Allowed ROE）维持在合理健康水平。\n </p>\n </div>\n </label>\n\n <!-- KPI 4 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 大纽约地区 AI 数据中心与建筑热泵电气化用电负荷增长率</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">长期成长新引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 关注曼哈顿科技金融中心算力升级及建筑脱碳改造带来的电力销售增量，评估其对总负荷曲线的正向拉动。\n </p>\n </div>\n </label>\n\n <!-- KPI 5 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 信用评级（S&P A- / Moody's A2）与长期债务再融资成本</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">资产负债表健康度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪降息周期中公司发行长期绿色债券的利率水平，确保利息保障倍数（ICR）与债务/EBITDA 指标保持在投资级安全边际。\n </p>\n </div>\n </label>\n\n <!-- KPI 6 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-edblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 季度股息宣告与连续第 52 年提息计划执行情况</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东回报承诺</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督每季度的分红派息公告，确保持续兑现股息伯爵的连年提息承诺，维护长期红利投资者的现金流预期。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明 (Disclaimer Footer)\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>爱迪生联合电气 Consolidated Edison, Inc. (NYSE: ED) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026Q3 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于爱迪生联合电气公开财务报告（10-Q/10-K）、2026Q3 业绩发布会披露数据及美国公用事业行业调研资料整理生成，旨在提供结构化的产业分析与红利资产估值框架。报告中涉及的盈利预测、资产基数增长率、三情景目标价及 DRIP 股息复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。跨境美股股息预扣税率因投资者国籍、税务居民身份及账户属性存在差异，请在独立核实后审慎决策。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n <script>\n // ==========================================\n // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n // ==========================================\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n // ==========================================\n // 2. 移动端抽屉菜单切换\n // ==========================================\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n // ==========================================\n // 3. 阅读进度条与左侧导航滚动联动高亮\n // ==========================================\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-edblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-edblue-400');\n }\n }\n });\n });\n\n // ==========================================\n // 4. 同行竞争格局矩阵筛选器\n // ==========================================\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-edblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-edblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n // ==========================================\n // 5. 爱迪生联合电气“股息伯爵”DRIP 复利与 Yield on Cost 动态推演器\n // ==========================================\n let currentTaxRate = 0.10; // 默认 10% 中美税收协定预扣税率\n\n function setTaxRate(rate) {\n currentTaxRate = rate;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnRate = parseFloat(btn.dataset.tax);\n if (Math.abs(btnRate - rate) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-edblue-500 text-white border border-edblue-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-edblue-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const drip = document.getElementById('drip-toggle').checked;\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initPrice = 106.50;\n const initDps = 3.55;\n const g = growthPct / 100;\n\n const initialShares = principal / initPrice;\n let shares = initialShares;\n let sharePrice = initPrice;\n let dps = initDps;\n let cashPool = 0;\n let cumulativeNetDiv = 0;\n\n for (let y = 1; y <= years; y++) {\n const grossDiv = shares * dps;\n const netDiv = grossDiv * (1 - currentTaxRate);\n cumulativeNetDiv += netDiv;\n\n // 股价按 EPS/股息增速同步稳健抬升\n const nextPrice = sharePrice * (1 + g);\n if (drip) {\n const avgReinvestPrice = (sharePrice + nextPrice) / 2;\n shares += netDiv / avgReinvestPrice;\n } else {\n cashPool += netDiv;\n }\n sharePrice = nextPrice;\n if (y < years) {\n dps = dps * (1 + g);\n }\n }\n\n const endForwardDps = initDps * Math.pow(1 + g, years);\n const endAnnualNetDiv = shares * endForwardDps * (1 - currentTaxRate);\n const finalPortfolioVal = (shares * sharePrice) + cashPool;\n const totalReturnPct = ((finalPortfolioVal - principal) / principal) * 100;\n const yieldOnCost = (endAnnualNetDiv / principal) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (${drip ? '含DRIP复利' : '现金分红留存'})`;\n document.getElementById('sim-annual-div').textContent = '$' + Math.round(endAnnualNetDiv).toLocaleString('en-US');\n document.getElementById('sim-monthly-div').textContent = `折合每月税后被动现金流 ~$${Math.round(endAnnualNetDiv / 12).toLocaleString('en-US')}`;\n document.getElementById('sim-yoc').textContent = yieldOnCost.toFixed(2) + '%';\n document.getElementById('sim-cum-div').textContent = '$' + Math.round(cumulativeNetDiv).toLocaleString('en-US');\n document.getElementById('sim-shares-end').textContent = `期末持仓股数：${shares.toFixed(1)} 股 (起始 ${initialShares.toFixed(1)} 股)`;\n }\n\n // ==========================================\n // 6. KPI 核查清单状态持久化与计数更新\n // ==========================================\n const KPI_STORAGE_KEY = 'ed_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {\n // 忽略本地存储权限限制\n }\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {\n // 忽略本地存储权限限制\n }\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n // ==========================================\n // 7. Chart.js 数据可视化初始化与主题自适应\n // ==========================================\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_profit';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n // 视图 A：2022–2026E 营业收入与净利润演进 ($B)\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '归母净利润 Net Income ($B)',\n data: [1.72, 1.78, 1.84, 1.89, 1.96],\n backgroundColor: '#0284C7',\n borderRadius: 4,\n stack: 'profit'\n },\n {\n type: 'line',\n label: '营业总收入 Total Revenues ($B)',\n data: [14.8, 15.2, 15.7, 16.1, 16.8],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 20,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n // 视图 B：业务分部资产与盈利贡献占比\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n 'CECONY 纽约电力配送 (Electric)',\n 'CECONY 天然气与蒸汽配送 (Gas & Steam)',\n 'O&R 郊区卫星电力与天然气',\n '清洁能源输配传输投资 (CETV)'\n ],\n datasets: [\n {\n label: '资产与盈利贡献比重 (%)',\n data: [75, 15, 6, 4],\n backgroundColor: [\n '#0284C7',\n '#06B6D4',\n '#10B981',\n '#6366F1'\n ],\n borderRadius: 6,\n barThickness: 24\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `资产与盈利分部占比: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 90,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_profit' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_profit') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-edblue-600 dark:text-edblue-400 shadow-sm transition cursor-pointer';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 营业收入与净利润演进路径';\n subEl.textContent = '得益于纽约电网费率重组与资本开支投放，净利润稳步上升至 ~$19.5亿 平台';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-edblue-600 dark:text-edblue-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '核心业务分部资产基数与盈利贡献拆解';\n subEl.textContent = 'CECONY 纽约市电力配送独占鳌头（占 ~75%），天然气与蒸汽系统提供坚实补充';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '特许经营与自然垄断',\n '监管资产回报保障(ROE)',\n '现金流稳健与透明度',\n '股息连年增长记录',\n '区域经济与AI用电增量'\n ],\n datasets: [\n {\n label: '爱迪生联合电气 (ED)',\n data: [9.9, 9.5, 9.8, 9.5, 9.2],\n borderColor: '#0284C7',\n backgroundColor: 'rgba(2, 132, 199, 0.24)',\n pointBackgroundColor: '#0284C7',\n borderWidth: 2.5\n },\n {\n label: 'NextEra Energy (NEE)',\n data: [8.5, 8.8, 8.2, 8.0, 9.5],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: 'Duke Energy (DUK)',\n data: [8.8, 8.6, 8.5, 7.8, 8.4],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '爱迪生联合电气 (ED · 纽约垄断龙头)',\n '杜克能源 (DUK · 美东南多州公用事业)',\n '南方公司 (SO · 核电与佐治亚大本营)',\n 'NextEra Energy (NEE · 绿能与佛州电力)'\n ],\n datasets: [\n {\n label: '远期市盈率 Forward P/E (倍)',\n data: [17.5, 17.0, 18.5, 22.0],\n backgroundColor: '#0284C7',\n borderRadius: 5,\n barThickness: 16\n },\n {\n label: '远期股息率 Dividend Yield (%)',\n data: [3.33, 3.95, 3.40, 2.75],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 16\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.dataset.label.includes('P/E') ? ctx.parsed.x + 'x' : ctx.parsed.x + '%'}`\n }\n }\n },\n scales: {\n x: {\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '调整后摊薄 EPS ($/股)',\n data: [4.15, 4.42, 4.88, 5.32, 5.68, 6.10],\n backgroundColor: 'rgba(2, 132, 199, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '年化每股现金分红 DPS ($/股)',\n data: [3.10, 3.16, 3.32, 3.40, 3.48, 3.55],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 2.5,\n max: 7.0,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(2) },\n title: { display: true, text: '每股收益与分红 ($/股)', color: colors.text, font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
